import {
  flexRender,
  useTable,
  type PaginationState,
  type RowData,
  type SortingState,
} from '@tanstack/react-table'
import {
  ChevronDown,
  ChevronLeft,
  ChevronRight,
  ChevronsLeft,
  ChevronsRight,
  ChevronUp,
  ChevronsUpDown,
  Search,
  X,
} from 'lucide-react'
import { useCallback, useEffect, useMemo, useRef, useState } from 'react'

import { For } from '~/components/utils/for'
import { Show } from '~/components/utils/show'
import { appTableFeatures, type AppColumnDef } from '~/lib/table'
import { cx } from '~/lib/cx'
import styles from './simple-data-table.module.scss'

type ClassValueOrFn<TContext> = string | ((context: TContext) => string)

export interface SimpleDataTableRowClassContext<TData> {
  row: TData
  rowIndex: number
  isEven: boolean
}

export interface SimpleDataTableCellClassContext<TData>
  extends SimpleDataTableRowClassContext<TData> {
  columnId: string
}

interface SimpleDataTableColumnMeta<TData> {
  headerClass?: string
  cellClass?: ClassValueOrFn<SimpleDataTableCellClassContext<TData>>
}

export interface SimpleDataTableClasses<TData> {
  toolbar?: string
  searchWrap?: string
  searchInput?: string
  actions?: string
  tableShell?: string
  table?: string
  head?: string
  headerRow?: string
  headerCell?: string
  body?: string
  row?: ClassValueOrFn<SimpleDataTableRowClassContext<TData>>
  cell?: ClassValueOrFn<SimpleDataTableCellClassContext<TData>>
  emptyState?: string
  pagination?: string
}

export type SimpleDataTableVariant = 'compact' | 'comfortable' | 'minimal'

function resolveClassName<TContext>(
  value: ClassValueOrFn<TContext> | undefined,
  context: TContext,
) {
  return typeof value === 'function' ? value(context) : value
}

function getColumnMeta<TData>(column: { columnDef: { meta?: unknown } }) {
  return column.columnDef.meta as SimpleDataTableColumnMeta<TData> | undefined
}

export interface SimpleDataTableProps<TData extends RowData> {
  data: TData[]
  columns: AppColumnDef<TData, unknown>[]
  searchable?: boolean
  searchPlaceholder?: string
  variant?: SimpleDataTableVariant
  pagination?: boolean
  initialPageSize?: number
  pageSizeOptions?: number[]
  loading?: boolean
  skeletonRows?: number
  emptyMessage?: string
  toolbarActions?: React.ReactNode
  classes?: SimpleDataTableClasses<TData>
  className?: string
}

function SortIcon({ direction }: { direction: 'asc' | 'desc' | false }) {
  return (
    <span className={styles.sortIcon}>
      <Show when={direction === 'asc'}>
        <ChevronUp aria-hidden />
      </Show>
      <Show when={direction === 'desc'}>
        <ChevronDown aria-hidden />
      </Show>
      <Show when={direction === false}>
        <ChevronsUpDown aria-hidden />
      </Show>
    </span>
  )
}

/** Lightweight client-side data table with search, sorting and pagination. */
export function SimpleDataTable<TData extends RowData>({
  data,
  columns,
  searchable,
  searchPlaceholder,
  variant = 'comfortable',
  pagination,
  initialPageSize,
  pageSizeOptions,
  loading,
  skeletonRows,
  emptyMessage,
  toolbarActions,
  classes,
  className,
}: SimpleDataTableProps<TData>) {
  const isSearchable = searchable !== false
  const isPaginationEnabled = pagination !== false
  const skeletonCount = skeletonRows ?? 4
  const pageSizes = pageSizeOptions ?? [10, 25, 50]

  const [searchInput, setSearchInput] = useState('')
  const [globalFilter, setGlobalFilter] = useState('')
  const [sorting, setSorting] = useState<SortingState>([])
  const [paginationState, setPaginationState] = useState<PaginationState>({
    pageIndex: 0,
    pageSize: initialPageSize ?? 10,
  })
  const debounceRef = useRef<ReturnType<typeof setTimeout> | undefined>(undefined)

  useEffect(() => () => clearTimeout(debounceRef.current), [])

  const handleSearch = useCallback((raw: string) => {
    setSearchInput(raw)
    clearTimeout(debounceRef.current)
    debounceRef.current = setTimeout(() => {
      setGlobalFilter(raw)
      setPaginationState((state) => ({ ...state, pageIndex: 0 }))
    }, 300)
  }, [])

  const clearSearch = useCallback(() => {
    setSearchInput('')
    setGlobalFilter('')
    setPaginationState((state) => ({ ...state, pageIndex: 0 }))
  }, [])

  const table = useTable({
    features: appTableFeatures,
    data,
    columns,
    state: { sorting, pagination: paginationState, globalFilter },
    onSortingChange: setSorting,
    onGlobalFilterChange: setGlobalFilter,
    onPaginationChange: setPaginationState,
    autoResetPageIndex: true,
  })

  const totalFiltered = table.getFilteredRowModel().rows.length
  const { pageIndex, pageSize } = paginationState
  const pageStart = pageIndex * pageSize + 1
  const pageEnd = Math.min(pageStart + pageSize - 1, totalFiltered)
  const visibleLeafColumns = table.getAllLeafColumns().filter((column) => column.getIsVisible())
  const skeletonIndices = useMemo(
    () => Array.from({ length: skeletonCount }, (_, index) => index),
    [skeletonCount],
  )

  return (
    <div
      className={cx(styles.root, className)}
      data-variant={variant}
    >
      {isSearchable || toolbarActions ? (
        <div className={cx(styles.toolbar, classes?.toolbar)}>
          {isSearchable ? (
            <div className={cx(styles.searchWrap, classes?.searchWrap)}>
              <span className={styles.searchIcon}>
                <Search aria-hidden />
              </span>
              <input
                type="search"
                value={searchInput}
                onChange={(event) => handleSearch(event.currentTarget.value)}
                placeholder={searchPlaceholder ?? 'Search…'}
                aria-label={searchPlaceholder ?? 'Search'}
                className={cx(styles.search, classes?.searchInput)}
              />
              {searchInput.length > 0 ? (
                <button
                  type="button"
                  onClick={clearSearch}
                  aria-label="Clear search"
                  className={styles.clear}
                >
                  <X aria-hidden />
                </button>
              ) : null}
            </div>
          ) : null}

          {toolbarActions ? (
            <div className={cx(styles.actions, classes?.actions)}>
              {toolbarActions}
            </div>
          ) : null}
        </div>
      ) : null}

      <div
        className={cx(styles.shell, classes?.tableShell)}
        tabIndex={0}
        role="region"
        aria-label="Table"
      >
        <table className={cx(styles.table, classes?.table)}>
          <thead className={cx(styles.head, classes?.head)}>
            <For each={table.getHeaderGroups()}>
              {(headerGroup) => (
                <tr key={headerGroup.id} className={classes?.headerRow}>
                  <For each={headerGroup.headers}>
                    {(header) => {
                      const columnMeta = getColumnMeta<TData>(header.column)
                      const canSort = header.column.getCanSort()
                      const sorted = header.column.getIsSorted()

                      return (
                        <th
                          key={header.id}
                          colSpan={header.colSpan}
                          scope="col"
                          aria-sort={
                            sorted === 'asc'
                              ? 'ascending'
                              : sorted === 'desc'
                                ? 'descending'
                                : canSort
                                  ? 'none'
                                  : undefined
                          }
                          className={cx(
                            styles.headerCell,
                            columnMeta?.headerClass,
                            classes?.headerCell,
                          )}
                        >
                          <Show when={!header.isPlaceholder}>
                            {canSort ? (
                              <button
                                type="button"
                                className={styles.sortButton}
                                onClick={header.column.getToggleSortingHandler()}
                              >
                                {flexRender(
                                  header.column.columnDef.header,
                                  header.getContext(),
                                )}
                                <SortIcon direction={sorted} />
                              </button>
                            ) : (
                              <span>
                                {flexRender(
                                  header.column.columnDef.header,
                                  header.getContext(),
                                )}
                              </span>
                            )}
                          </Show>
                        </th>
                      )
                    }}
                  </For>
                </tr>
              )}
            </For>
          </thead>

          <tbody className={cx(styles.body, classes?.body)}>
            {loading ? (
              <For each={skeletonIndices}>
                {(index) => (
                  <tr key={`skeleton-${index}`} className={styles.row}>
                    <For each={visibleLeafColumns}>
                      {(column) => (
                        <td key={column.id} className={styles.cell}>
                          <div className={styles.skeleton} />
                        </td>
                      )}
                    </For>
                  </tr>
                )}
              </For>
            ) : table.getRowModel().rows.length > 0 ? (
              <For each={table.getRowModel().rows}>
                {(row) => {
                  const rowContext: SimpleDataTableRowClassContext<TData> = {
                    row: row.original,
                    rowIndex: row.index,
                    isEven: row.index % 2 === 0,
                  }

                  return (
                    <tr
                      key={row.id}
                      className={cx(
                        styles.row,
                        resolveClassName(classes?.row, rowContext),
                      )}
                    >
                      <For each={row.getVisibleCells()}>
                        {(cell) => {
                          const cellContext: SimpleDataTableCellClassContext<TData> = {
                            ...rowContext,
                            columnId: cell.column.id,
                          }
                          const columnMeta = getColumnMeta<TData>(cell.column)

                          return (
                            <td
                              key={cell.id}
                              className={cx(
                                styles.cell,
                                resolveClassName(classes?.cell, cellContext),
                                resolveClassName(columnMeta?.cellClass, cellContext),
                              )}
                            >
                              {flexRender(
                                cell.column.columnDef.cell,
                                cell.getContext(),
                              )}
                            </td>
                          )
                        }}
                      </For>
                    </tr>
                  )
                }}
              </For>
            ) : (
              <tr>
                <td
                  colSpan={visibleLeafColumns.length}
                  className={cx(styles.empty, classes?.emptyState)}
                >
                  {emptyMessage ?? 'No results found.'}
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>

      {isPaginationEnabled ? (
        <div className={cx(styles.pagination, classes?.pagination)}>
          <div className={styles.info}>
            {totalFiltered > 0 ? (
              <span>
                Showing{' '}
                <span className={styles.strong}>
                  {pageStart}–{pageEnd}
                </span>{' '}
                of <span className={styles.strong}>{totalFiltered}</span>
              </span>
            ) : null}

            <label className={styles.pageSize}>
              <span>Rows:</span>
              <select
                value={pageSize}
                onChange={(event) =>
                  table.setPageSize(Number(event.currentTarget.value))
                }
                className={styles.select}
              >
                <For each={pageSizes}>
                  {(size) => (
                    <option key={size} value={size}>
                      {size}
                    </option>
                  )}
                </For>
              </select>
            </label>
          </div>

          <div className={styles.pages}>
            <button
              type="button"
              disabled={!table.getCanPreviousPage()}
              onClick={() => table.firstPage()}
              className={styles.pageButton}
              aria-label="First page"
            >
              <ChevronsLeft aria-hidden />
            </button>
            <button
              type="button"
              disabled={!table.getCanPreviousPage()}
              onClick={() => table.previousPage()}
              className={styles.pageButton}
              aria-label="Previous page"
            >
              <ChevronLeft aria-hidden />
            </button>

            <For each={pageNumbers(table.getPageCount(), pageIndex)}>
              {(item, index) =>
                item === '…' ? (
                  <span key={`page-${index}`} className={styles.ellipsis}>
                    <span aria-hidden>…</span>
                    <span className="vz-sr-only">More pages</span>
                  </span>
                ) : (
                  <button
                    key={`page-${index}`}
                    type="button"
                    onClick={() => table.setPageIndex(Number(item) - 1)}
                    aria-label={`Page ${item}`}
                    aria-current={
                      pageIndex === Number(item) - 1 ? 'page' : undefined
                    }
                    className={cx(
                      styles.pageNumber,
                      pageIndex === Number(item) - 1 && styles.pageNumberActive,
                    )}
                  >
                    {item}
                  </button>
                )
              }
            </For>

            <button
              type="button"
              disabled={!table.getCanNextPage()}
              onClick={() => table.nextPage()}
              className={styles.pageButton}
              aria-label="Next page"
            >
              <ChevronRight aria-hidden />
            </button>
            <button
              type="button"
              disabled={!table.getCanNextPage()}
              onClick={() => table.lastPage()}
              className={styles.pageButton}
              aria-label="Last page"
            >
              <ChevronsRight aria-hidden />
            </button>
          </div>
        </div>
      ) : null}
    </div>
  )
}

function pageNumbers(total: number, current: number): (string | '…')[] {
  if (total <= 7) {
    return Array.from({ length: total }, (_, index) => String(index + 1))
  }
  const pages: (string | '…')[] = []
  const add = (page: number) => pages.push(String(page))
  add(1)
  if (current > 3) pages.push('…')
  for (let page = Math.max(2, current); page <= Math.min(total - 1, current + 2); page += 1) {
    add(page)
  }
  if (current < total - 3) pages.push('…')
  add(total)
  return pages
}

@use 'styles' as vz;

.root {
  display: flex;
  flex-direction: column;
  gap: vz.space(4);
  width: 100%;
}

.toolbar {
  display: flex;
  flex-direction: column;
  gap: vz.space(2);
}

.search-wrap {
  position: relative;
  width: 100%;
}

.search-icon {
  position: absolute;
  top: 50%;
  left: vz.space(3);
  color: vz.color('muted-foreground');
  pointer-events: none;
  transform: translateY(-50%);

  svg {
    @include vz.icon(3.5);
  }
}

.search {
  width: 100%;
  height: vz.space(9);
  padding: 0 vz.space(8) 0 vz.space(8);
  border: 1px solid vz.color('border');
  border-radius: vz.radius('lg');
  background: vz.color('card');
  color: vz.color('foreground');
  font-size: vz.font-size('sm');
  outline: none;
  transition:
    border-color vz.duration('fast') vz.ease('out'),
    box-shadow vz.duration('fast') vz.ease('out');

  @include vz.placeholder {
    color: vz.color('muted-foreground');
  }

  &:focus-visible {
    border-color: vz.color('primary');
    box-shadow: 0 0 0 3px vz.color('primary', 0.18);
  }

  &::-webkit-search-cancel-button {
    appearance: none;
  }
}

.clear {
  position: absolute;
  top: 50%;
  right: vz.space(2.5);
  display: inline-flex;
  width: vz.space(6);
  height: vz.space(6);
  align-items: center;
  justify-content: center;
  border: 0;
  border-radius: vz.radius('xs');
  background: transparent;
  color: vz.color('muted-foreground');
  cursor: pointer;
  transform: translateY(-50%);

  @include vz.hover {
    color: vz.color('foreground');
  }

  @include vz.focus-ring(2px, 1px, 0.6);

  svg {
    @include vz.icon(3);
  }
}

.actions {
  display: flex;
  flex: none;
  align-items: center;
  gap: vz.space(2);
}

.shell {
  overflow-x: auto;
  border: 1px solid vz.color('border');
  border-radius: vz.radius('2xl');
  background: vz.color('card');
  outline: none;

  &:focus-visible {
    outline: 2px solid vz.color('ring', 0.6);
    outline-offset: 2px;
  }

  @include vz.scrollbar(10px);
}

.table {
  width: 100%;
  min-width: max-content;
  border-collapse: collapse;
  font-size: vz.font-size('sm');
}

.head {
  border-bottom: 1px solid vz.color('border');
  background: vz.color('muted', 0.55);
}

.header-cell {
  padding: vz.space(2.5) vz.space(4);
  color: vz.color('muted-foreground');
  font-size: vz.font-size('xs');
  font-weight: 600;
  text-align: left;
  white-space: nowrap;
  user-select: none;
}

.sort-button {
  display: inline-flex;
  align-items: center;
  gap: vz.space(1);
  padding: 0;
  border: 0;
  border-radius: vz.radius('xs');
  background: transparent;
  color: inherit;
  font: inherit;
  cursor: pointer;

  @include vz.hover {
    color: vz.color('foreground');
  }

  @include vz.focus-ring(2px, 1px, 0.6);
}

.sort-icon {
  display: inline-flex;
  flex: none;
  color: vz.color('muted-foreground');

  svg {
    @include vz.icon(3);
  }
}

.body {
  background: vz.color('card');
}

.row {
  border-bottom: 1px solid vz.color('border', 0.7);
  transition: background-color vz.duration('fast') vz.ease('out');

  &:last-child {
    border-bottom: 0;
  }

  @include vz.hover {
    background: vz.color('accent');
  }
}

:global(.dark) .shell {
  border-color: vz.color('border', 0.9);
  background: vz.color('card');
  box-shadow: none;
}

:global(.dark) .head {
  background: vz.color('muted', 0.75);
}

:global(.dark) .row {
  border-bottom-color: vz.color('border', 0.65);
}

:global(.dark) .row:hover {
  background: vz.color('accent', 0.8);
}

.cell {
  padding: vz.space(3) vz.space(4);
  color: vz.color('foreground');
  font-size: vz.font-size('sm');
  line-height: 1.45;
  vertical-align: middle;
}

.empty {
  padding: vz.space(10) vz.space(4);
  color: vz.color('muted-foreground');
  font-size: vz.font-size('sm');
  text-align: center;
}

.skeleton {
  height: vz.space(4);
  width: 75%;
  border-radius: vz.radius('xs');
  background: vz.color('muted');
  animation: vz-table-pulse 1.6s vz.ease('in-out') infinite;

  @include vz.motion-reduce {
    animation: none;
  }
}

.pagination {
  display: flex;
  flex-direction: column;
  gap: vz.space(3);
  padding-inline: vz.space(0.5);
  color: vz.color('muted-foreground');
  font-size: vz.font-size('sm');
}

.info {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: vz.space(3);
}

.strong {
  color: vz.color('foreground');
  font-weight: 600;
}

.page-size {
  display: flex;
  align-items: center;
  gap: vz.space(1.5);
}

.select {
  height: vz.space(7);
  padding-inline: vz.space(1.5);
  border: 1px solid vz.color('border');
  border-radius: vz.radius('md');
  background: vz.color('card');
  color: vz.color('foreground');
  font-size: vz.font-size('sm');
  outline: none;

  &:focus-visible {
    outline: 2px solid vz.color('ring', 0.6);
    outline-offset: 1px;
  }
}

.pages {
  display: flex;
  align-items: center;
  gap: vz.space(1);
}

.page-button {
  display: flex;
  width: vz.space(8);
  height: vz.space(8);
  align-items: center;
  justify-content: center;
  border: 1px solid vz.color('border');
  border-radius: vz.radius('lg');
  background: vz.color('card');
  color: vz.color('foreground');
  cursor: pointer;
  transition:
    background-color vz.duration('fast') vz.ease('out'),
    border-color vz.duration('fast') vz.ease('out');

  @include vz.hover {
    background: vz.color('accent');
  }

  @include vz.focus-ring(2px, 1px, 0.6);

  @include vz.disabled {
    opacity: 0.4;
    pointer-events: none;
  }

  svg {
    @include vz.icon(3.5);
  }
}

.page-number {
  display: flex;
  min-width: vz.space(8);
  height: vz.space(8);
  align-items: center;
  justify-content: center;
  padding-inline: vz.space(2);
  border: 1px solid vz.color('border');
  border-radius: vz.radius('lg');
  background: vz.color('card');
  color: vz.color('foreground');
  font-size: vz.font-size('sm');
  font-weight: 500;
  cursor: pointer;

  @include vz.hover {
    background: vz.color('accent');
  }

  @include vz.focus-ring(2px, 1px, 0.6);
}

.page-number-active {
  border-color: vz.color('primary');
  background: vz.color('primary');
  color: vz.color('primary-foreground');
}

.ellipsis {
  padding-inline: vz.space(1.5);
  color: vz.color('muted-foreground');
}

// ── Variants ────────────────────────────────────────────
.root[data-variant='compact'] .search {
  height: vz.space(8);
  font-size: vz.font-size('xs');
}

.root[data-variant='compact'] .shell {
  border-radius: vz.radius('xl');
}

.root[data-variant='compact'] .head {
  background: vz.color('muted', 0.4);
}

.root[data-variant='compact'] .header-cell {
  padding: vz.space(2) vz.space(3);
  font-size: 0.6875rem;
  font-weight: 500;
}

.root[data-variant='compact'] .cell {
  padding: vz.space(2.5) vz.space(3);
  font-size: 0.8125rem;
}

.root[data-variant='minimal'] .shell {
  border-color: transparent;
  border-radius: vz.radius('xl');
  background: transparent;
}

.root[data-variant='minimal'] .head {
  background: transparent;
}

.root[data-variant='minimal'] .header-cell {
  padding: vz.space(2) vz.space(4);
  font-size: 0.6875rem;
  font-weight: 500;
}

.root[data-variant='minimal'] .row {
  background: transparent;
}

.root[data-variant='minimal'] .cell {
  padding: vz.space(3) vz.space(4);
}

@include vz.up('sm') {
  .toolbar {
    flex-direction: row;
    align-items: center;
    justify-content: space-between;
  }

  .search-wrap {
    width: 13rem;
  }

  .pagination {
    flex-direction: row;
    align-items: center;
    justify-content: space-between;
  }
}

@keyframes vz-table-pulse {
  0%,
  100% {
    opacity: 1;
  }

  50% {
    opacity: 0.5;
  }
}
